/*!
 * Cheshire Trade Centre — stock filter for the static export.
 *
 * The site is generated by the PHP build, where filtering and pagination happen
 * server-side. This export ships every vehicle on one page, so the same filter
 * is done client-side here to keep the preview honest.
 *
 * Reads: make, model, bodytype, min_price, max_price, sort from the query string.
 * Writes: nothing but the DOM — and the query string, via replaceState, so a
 * filtered view can be linked to and shared.
 */
(function () {
  'use strict';

  var CARD = '.card.text-bg-card-l.h-100.vehicle';
  var cards = Array.prototype.slice.call(document.querySelectorAll(CARD));
  if (!cards.length) return;

  var heading = Array.prototype.slice.call(document.querySelectorAll('h1, h2')).filter(function (el) {
    return /vehicles? in stock/i.test(el.textContent || '');
  })[0] || null;

  var FILTERS = ['make', 'model', 'bodytype', 'min_price', 'max_price'];

  function toNum(v) {
    if (v === null || v === undefined || v === '') return null;
    var n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
    return isNaN(n) ? null : n;
  }

  function cardData(card) {
    var d = card.dataset || {};
    return {
      make: d.make || '',
      model: d.model || '',
      body: d.body || '',
      price: toNum(d.price),
      year: toNum(d.year),
      mileage: toNum(d.mileage)
    };
  }

  function sortCards(order) {
    // card -> .col wrapper -> the grid row
    var row = cards[0] && cards[0].parentElement && cards[0].parentElement.parentElement;
    if (!row) return;
    var plain = cards.slice();
    var key, dir;
    switch (order) {
      case 'price-asc':  key = 'price'; dir = 1; break;
      case 'price-desc': key = 'price'; dir = -1; break;
      case 'mileage-asc':  key = 'mileage'; dir = 1; break;
      case 'mileage-desc': key = 'mileage'; dir = -1; break;
      case 'date-asc':   key = 'year'; dir = 1; break;
      case 'date-desc':  key = 'year'; dir = -1; break;
      default: return;
    }
    plain.sort(function (a, b) {
      var av = cardData(a)[key], bv = cardData(b)[key];
      if (av === null && bv === null) return 0;
      if (av === null) return 1;
      if (bv === null) return -1;
      if (av === bv) {
        // stable tiebreak: newest and dearest first, then slug
        return (a.dataset.slug || '').localeCompare(b.dataset.slug || '');
      }
      return (av - bv) * dir;
    });
    var frag = document.createDocumentFragment();
    plain.forEach(function (c) {
      var wrap = c.parentElement;
      if (wrap) frag.appendChild(wrap);
    });
    row.appendChild(frag);
  }

  function ensureNotice() {
    var el = document.getElementById('stock-no-results');
    if (el) return el;
    el = document.createElement('div');
    el.id = 'stock-no-results';
    el.className = 'alert alert-secondary my-4 text-center';
    el.style.display = 'none';
    el.innerHTML = 'No vehicles match those filters. ' +
      '<a href="stock.html" class="alert-link">Show all cars</a>.';
    var row = cards[0].parentElement;
    if (row && row.parentElement) row.parentElement.insertBefore(el, row);
    return el;
  }

  function syncControls(params) {
    var names = FILTERS.concat(['sort']);
    document.querySelectorAll('form[action$="stock.html"]').forEach(function (form) {
      names.forEach(function (name) {
        var sel = form.querySelector('[name="' + name + '"]');
        if (!sel) return;
        var want = params.get(name);
        if (want === null) return;
        // the model list is rebuilt by site.js, so retry once it has options
        if (name === 'model' && sel.options.length < 2) {
          window.setTimeout(function () { sel.value = want; }, 60);
        } else {
          sel.value = want;
        }
      });
    });
  }

  function apply(params, updateUrl) {
    var make = (params.get('make') || '').trim();
    var model = (params.get('model') || '').trim();
    var body = (params.get('bodytype') || '').trim();
    var min = toNum(params.get('min_price'));
    var max = toNum(params.get('max_price'));

    var shown = 0;
    cards.forEach(function (card) {
      var d = cardData(card);
      var ok = true;
      if (make && d.make !== make) ok = false;
      if (ok && model && d.model !== model) ok = false;
      if (ok && body && d.body !== body) ok = false;
      if (ok && min !== null && d.price !== null && d.price < min) ok = false;
      if (ok && max !== null && d.price !== null && d.price > max) ok = false;
      var wrap = card.parentElement;
      if (wrap) wrap.style.display = ok ? '' : 'none';
      if (ok) shown += 1;
    });

    if (heading) {
      heading.textContent = shown + (shown === 1 ? ' vehicle in stock' : ' vehicles in stock');
    }
    var notice = ensureNotice();
    if (notice) notice.style.display = shown ? 'none' : '';

    var sort = params.get('sort');
    if (sort) sortCards(sort);

    syncControls(params);

    if (updateUrl) {
      var qs = params.toString();
      try {
        history.replaceState(null, '', qs ? '?' + qs : window.location.pathname);
      } catch (e) { /* file:// — ignore */ }
    }
    return shown;
  }

  function paramsFrom(form) {
    var params = new URLSearchParams();
    new FormData(form).forEach(function (value, key) {
      if (value !== null && String(value).trim() !== '') params.set(key, value);
    });
    return params;
  }

  // Filter in place rather than reloading: the whole stock is on this page.
  document.querySelectorAll('form[action$="stock.html"]').forEach(function (form) {
    form.addEventListener('submit', function (ev) {
      var hasFilter = form.querySelector('[name="make"], [name="bodytype"], [name="min_price"], [name="max_price"], [name="sort"]');
      if (!hasFilter) return;
      ev.preventDefault();
      apply(paramsFrom(form), true);
      var target = document.getElementById('stocklist');
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });

  // Any in-page filter link (?make=Audi etc.) filters without a round trip.
  document.addEventListener('click', function (ev) {
    var a = ev.target.closest ? ev.target.closest('a[href*="stock.html?"]') : null;
    if (!a) return;
    var url;
    try { url = new URL(a.getAttribute('href'), window.location.href); } catch (e) { return; }
    if (url.pathname.split('/').pop() !== 'stock.html') return;
    ev.preventDefault();
    apply(new URLSearchParams(url.search), true);
    var target = document.getElementById('stocklist');
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  apply(new URLSearchParams(window.location.search), false);
})();
